\begin{equation}\label{RMT-model} 
\begin{split}
 \mathcal{D} =\left(\begin{array}{cc} 0 & iW \\ iW^\dagger & 0 \end{array}\right), ~
 W= H_1+i\mu H_2,\\
 H_1,H_2\in{\rm Herm}(N)\ \text{and}\ \mu\in[0,1]~~~
\end{split}
\end{equation}

\begin{equation}\label{distribution}
P(\mathcal{D})= \frac{1}{2^N \pi^{N^2}}\exp\left[-\frac{1}{2}\text{tr}(H_1^2+H_2^2)\right].
\end{equation}

The partition function with $N_{\rm f}$ dynamical quarks with masses $m_1,\ldots,m_{N_{\rm f}}$ is then given by
\begin{equation}\label{eq:0Zdef}
		Z_N^{(N_f)} = \int d\mathcal{D} P(\mathcal{D})\prod_{f=1}^{N_{\rm f}}\det(m_f \mathbb{1}_{2N} +\mathcal{D})\,.
\end{equation}

\begin{equation}\label{eq:0Zdef}
		Z_N^{(N_f)} = \int d\mathcal{D} P(\mathcal{D})\prod_{f=1}^{N_{\rm f}}\det(m_f \mathbb{1}_{2N} +\mathcal{D})\,.
\end{equation}

The Euclidean Lagrangian is given by
\begin{equation}\label{Lag-phys}
\begin{split}
	 \mathcal{L} = & \overline{\psi}\bigl(\mathcal{D}_{\rm 3d}
	 + \mu_{\rm I} \sigma_3\tau_3+{\rm diag}(m_{\rm u},m_{\rm d})+j\tau_1\bigl)\psi,
\end{split}
\end{equation}
where $\mathcal{D}_{\rm 3d}$ is the 3d Dirac operator which is anti-Hermitian, $\psi$ the two-flavor quark fields, $\mu_{\rm I}$ the isospin chemical potential, $m_{\rm u/d}$ the quark masses, $j$ the source term for the pion condensate, and $\tau_j$ and $\sigma_3$ the Pauli matrices in flavour space and spinor space, respectively.

\begin{equation}\label{Lag-phys}
\begin{split}
	 \mathcal{L} = & \overline{\psi}\bigl(\mathcal{D}_{\rm 3d}
	 + \mu_{\rm I} \sigma_3\tau_3+{\rm diag}(m_{\rm u},m_{\rm d})+j\tau_1\bigl)\psi,
\end{split}
\end{equation}

To this aim, we consider the partition function involving $k$ bosonic quarks and $N_{\rm f}+k$ fermionic quarks 
\begin{equation}\label{eq:Zval}
		Z_N^{(k,N_{\rm f}+k)} = \int d\mathcal{D} P(\mathcal{D})\frac{\prod_{j=1}^{N_{\rm f}+k}\det(\kappa_{{\rm f}, j} \mathbb{1}_{2N}+\mathcal{D})}{\prod_{j=1}^{k}\det(\kappa_{{\rm b}, j} \mathbb{1}_{2N}+\mathcal{D})},
\end{equation}
with $k=0$ for the ordinary fermionic partition function and $k=1$ and $N_{\rm f}=0$ for the quenched microscopic level density.

\begin{equation}\label{eq:Zval}
		Z_N^{(k,N_{\rm f}+k)} = \int d\mathcal{D} P(\mathcal{D})\frac{\prod_{j=1}^{N_{\rm f}+k}\det(\kappa_{{\rm f}, j} \mathbb{1}_{2N}+\mathcal{D})}{\prod_{j=1}^{k}\det(\kappa_{{\rm b}, j} \mathbb{1}_{2N}+\mathcal{D})},
\end{equation}

\begin{equation}\label{susy:partiton}
\begin{split}
		Z_N^{(k,N_{\rm f}+k)} = \; &\frac{1}{\pi^{2 Nk}}\int dV 
		\exp\big[\! -L\; \text{Str}\,V^\dagger V\kappa \\
		&-\text{Str}  (V^\dagger V\tau_1)^2/2-\mu^2\text{Str} (V^\dagger V\tau_2)^2/2 \big].
\end{split}
\end{equation}

In the next step we apply the superbosonization formula~\cite{Zirnbauer:2006,Kieburg:2008} and replace
\begin{equation}
LV^\dagger V\tau_1\rightarrow \sqrt{N} U'=\sqrt{N}\left(\begin{array}{cc} U'_{\rm bb} & \eta^\dagger \\ \eta & U'_{\rm ff} \end{array}\right),
\end{equation}
where the the boson-boson block $U'_{\rm bb}$ satisfies $LU'_{\rm bb}\tau_1=(LU'_{\rm bb}\tau_1)^\dagger>0$ and the fermion-fermion block $U'_{\rm ff}$ is unitary.

\begin{equation}
LV^\dagger V\tau_1\rightarrow \sqrt{N} U'=\sqrt{N}\left(\begin{array}{cc} U'_{\rm bb} & \eta^\dagger \\ \eta & U'_{\rm ff} \end{array}\right),
\end{equation}

In terms of this supermatrix, the partition function is up to a global constant equal to
\begin{equation}\label{susy:partiton.b}
\begin{split}
		Z_N^{(k_{\rm b},k_{\rm f})} \propto&
		\int d\tilde{\mu}(U')\; \text{Sdet}^{N}U' \exp\big[\!-\text{Str}\,U'\widehat{\kappa}\tau_1
		\\
		& - N\, \text{Str}\,{U'}^2/2 + \widehat{\mu}^2\text{Str} (U'\tau_3)^2/2 \big].
\end{split}
\end{equation}

\begin{equation}\label{susy:partiton.b}
\begin{split}
		Z_N^{(k_{\rm b},k_{\rm f})} \propto&
		\int d\tilde{\mu}(U')\; \text{Sdet}^{N}U' \exp\big[\!-\text{Str}\,U'\widehat{\kappa}\tau_1
		\\
		& - N\, \text{Str}\,{U'}^2/2 + \widehat{\mu}^2\text{Str} (U'\tau_3)^2/2 \big].
\end{split}
\end{equation}

First we want to consider the partition function with $N_{\rm f}$ dynamical quarks, i.e. $k=0$ \cite{comm}. There is no supersymmetry and the whole supermatrix consists of the fermion-fermion block, only, $U'=U_{\rm ff}$. For $N\to\infty$ we have to solve the saddle point equation
\begin{equation}\label{sad.eq}
 U'^2=\mathbb{1}_{2N_{\rm f}}.
\end{equation}
This implies that all eigenvalues of $U'$ are $\pm1$. When diagonalizing $U'$ to its eigenvalues $e^{i \phi}=\text{diag}(e^{i \phi_1},\ldots,e^{i \phi_{N_{\rm f}}})$ we would obtain the Vandermonde term $|\Delta_{N_{\rm f}}(e^{i \phi})|^2=\prod_{a<b}|e^{i \phi_b}-e^{i \phi_a}|^2$ as the Jacobian. This term algebraically suppresses all solutions of~\eqref{sad.eq} in $1/N$ which do not have an equal number of $\pm1$. Thus we integrate only over the coset ${\rm U}(2N_{\rm f})/[{\rm U}(N_{\rm f})\times {\rm U}(N_{\rm f})]$ which is the same as for $\mu=0$ (GUE, 3d QCD), see~\cite{Verbaarschot:1994ip}. This coset can be parametrized as $U'=U\tau_3 U^\dagger$ with $U\in{\rm U}(2N_{\rm f})$.

\begin{equation}\label{sad.eq}
 U'^2=\mathbb{1}_{2N_{\rm f}}.
\end{equation}

\begin{align}\label{k-flav-f}
Z^{(0,N_{\rm f})}=\!\!\!\!\! \int\limits_{\text{U}(2N_{\rm f})} \!\!\!\!\!\!
d\mu(U)\exp\left[\text{tr}\,U\tau_3U^\dagger \widehat{\kappa}\tau_1-\frac{\widehat{\mu}^2}{2}\text{tr}(U\tau_3U^\dagger\tau_3)^2\right]\!.
\end{align}

Next we want to derive the microscopic level density in the quenched limit. Its relation to the partially quenched partition function for $k=1$ and $N_{\rm f}=0$ is
\begin{equation}\label{level-part}
\rho(\lambda)=\frac{1}{\pi}\lim_{\varepsilon\to0}{\rm Re}\left.\partial_{\widehat{\kappa}_{\rm f}}Z_N^{(1,1)}\right|_{\widehat{\kappa}_{\rm b}=\widehat{\kappa}_{\rm f}=L\varepsilon-i \lambda}.
\end{equation}
In the large-$N$ limit the saddle point equation~\eqref{sad.eq} still applies though with a different dimension in the unit matrix. For this reason we use the parametrization
\begin{equation}
\begin{split}
{U'}_{\rm bb}& = Le^{-\vartheta_1\tau_3/2}e^{-\vartheta_2\tau_2/2}\tau_1e^{z_1\mathbb{1}_2+z_2 \tau_1}e^{\vartheta_2\tau_2/2}e^{\vartheta_1\tau_3/2},\\
{U'}_{\rm ff}& = e^{-i\varphi_1\tau_3/2}e^{-i\varphi_2\tau_2/2}\tau_1e^{i(z_3\mathbb{1}_2+z_4 \tau_1)}e^{i\varphi_2\tau_2/2}e^{i\varphi_1\tau_3/2},
\end{split}
\end{equation}
for the two diagonal blocks of $U'$. The angles take the values $z_1,z_2,\vartheta_1,\vartheta_2\in\mathbb{R}$, $\varphi_1\in[-\pi,\pi]$, and $\varphi_2,z_3,z_4\in[-\pi/2,\pi/2]$. From the saddle point equation and the properties of ${U'}_{\rm bb}$ and ${U'}_{\rm ff}$ we have to expand the variables $z_j$ as follows: $(z_1,z_2)=(\delta z_1/\sqrt{N},\delta z_2/\sqrt{N})$ and $(z_3,z_4)=(\delta z_3/\sqrt{N},$ $\delta z_4/\sqrt{N}), ~(z_3,z_4)=(\pi/2+\delta z_3/\sqrt{N},\pi/2+\delta z_4/\sqrt{N})$. The latter expansion for $z_3,z_4$ yields an algebraically $1/N$-suppressed term. The expansion to leading order in $1/N$ and integration over $\eta$ and $\delta z_j$ is quite lengthy and we omit it here.

\begin{equation}\label{level-part}
\rho(\lambda)=\frac{1}{\pi}\lim_{\varepsilon\to0}{\rm Re}\left.\partial_{\widehat{\kappa}_{\rm f}}Z_N^{(1,1)}\right|_{\widehat{\kappa}_{\rm b}=\widehat{\kappa}_{\rm f}=L\varepsilon-i \lambda}.
\end{equation}

\begin{equation}
\begin{split}
{U'}_{\rm bb}& = Le^{-\vartheta_1\tau_3/2}e^{-\vartheta_2\tau_2/2}\tau_1e^{z_1\mathbb{1}_2+z_2 \tau_1}e^{\vartheta_2\tau_2/2}e^{\vartheta_1\tau_3/2},\\
{U'}_{\rm ff}& = e^{-i\varphi_1\tau_3/2}e^{-i\varphi_2\tau_2/2}\tau_1e^{i(z_3\mathbb{1}_2+z_4 \tau_1)}e^{i\varphi_2\tau_2/2}e^{i\varphi_1\tau_3/2},
\end{split}
\end{equation}

One important identity for the Bessel functions is the following~\cite[Eq.~(9.6.1)]{Abramowitz},
\begin{equation}
\lim_{\varepsilon\to0}{\rm Im}(\varepsilon-i \lambda)^\nu K_\nu(2(\varepsilon-i \lambda)\cosh\vartheta_2)=\frac{\pi}{2}\lambda^\nu J_\nu(2\lambda\cosh\vartheta_2)
\end{equation}
which simplifies the result a lot.

Substituting $x=\sin\varphi_2$ and $y=\sinh\vartheta_2$, we eventually obtain an expression for the microscopic level density of the quenched system,
\begin{widetext}
\begin{align}
\rho(\lambda)=\;&\frac{2}{\pi}\int_{-1}^1 dx\int_{-\infty}^\infty dy\exp\left[-2\widehat{\mu}^2\left(x^2+y^2\right)\right]\biggl[\left(2\widehat{\mu}^4(y^2-x^2+1)(y^2-x^2)-\widehat{\mu}^2\frac{x^2+y^2}{2}-\frac{1}{2}\lambda^2(2+y^2-x^2)-\frac{1}{4}\right)\notag\\
&\times\sqrt{1-x^2} J_1(2|\lambda|\sqrt{1-x^2})J_0(2\lambda\sqrt{1+y^2})+\lambda^2(1-x^2)\sqrt{1+y^2}J_0(2\lambda\sqrt{1-x^2})J_1(2|\lambda|\sqrt{1+y^2})\notag\\
&+\left(2\widehat{\mu}^2(y^2-x^2+1)+\frac{1}{4}\right)|\lambda|(1-x^2)J_0(2\lambda\sqrt{1-x^2})J_0(2\lambda\sqrt{1+y^2})\notag\\
&+\left(2\widehat{\mu}^2(y^2-x^2+1)+\frac{1}{4}\right)|\lambda|\sqrt{1+y^2}\sqrt{1-x^2}J_1(2\lambda\sqrt{1-x^2})J_1(2\lambda\sqrt{1+y^2})\biggl]\,.
\label{level.density}
\end{align}
\end{widetext}
